<?php include "../auth/cek_login.php";include "../koneksi.php";if($_SESSION['role']!='admin')die('Akses ditolak');if(isset($_POST['simpan'])){mysqli_query($conn,"INSERT INTO users(username,password,nama,role) VALUES ('$_POST[username]',MD5('$_POST[password]'),'$_POST[nama]','$_POST[role]')");header("Location:index.php");exit;}?><!doctype html><html><head><title>Tambah User</title><link rel="stylesheet" href="../assets/style.css"></head><body><div class="content"><h1>Tambah User</h1><form method="post"><input name="username" placeholder="Username" required><input type="password" name="password" placeholder="Password" required><input name="nama" placeholder="Nama" required><select name="role"><option value="petugas">Petugas</option><option value="admin">Admin</option></select><button name="simpan">Simpan</button></form></div></body></html>